/*
 * A062505  Numbers k such that if p is a prime that divides k, then either p
 *          + 2 or p - 2 is also prime.
 * https://oeis.org/A062505
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 95, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by searching for the smallest integer k ≥ 1 such that
   every prime divisor p of k satisfies that either p+2 or p−2 is prime (p≠2).
   The function performs this search lazily and caches the results.
   // No closed form formula exists. */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>

/* ----------  Prime utilities (self‑contained)  ---------- */

static uint64_t *prime_list = NULL;     /* array of discovered primes  */
static size_t prime_count = 0;          /* number of stored primes     */
static size_t prime_cap   = 0;          /* current capacity of array   */

/* Integer square root (floor), 64‑bit */
static inline uint64_t isqrt_uint64(uint64_t n)
{
    uint64_t r = 0;
    for (int k = 30; k >= 0; --k) {
        uint64_t d = r | (1ULL << k);
        if (d * d <= n)
            r = d;
    }
    return r;
}

/* Grow the prime list until it contains all primes ≤ limit. */
static void extend_prime_list(uint64_t limit)
{
    if (prime_list == NULL) {          /* first time */
        prime_cap = 64;
        prime_list = (uint64_t *)malloc(prime_cap * sizeof(uint64_t));
        prime_list[0] = 2;
        prime_count = 1;
    }

    uint64_t start = prime_list[prime_count - 1] + 1;
    if ((limit & 1) == 0) {
        if (limit >= 2 && start <= 3) start = 3;
        else if (start % 2 == 0) ++start;
    } else if (start % 2 == 0) ++start;

    for (uint64_t n = start; n <= limit; n += 2) {
        /* Test n against known primes up to sqrt(n) */
        uint64_t lim = isqrt_uint64(n);
        bool prime = true;
        for (size_t i = 0; i < prime_count; ++i) {
            uint64_t p = prime_list[i];
            if (p > lim) break;
            if (n % p == 0) { prime = false; break; }
        }
        if (prime) {
            if (prime_count == prime_cap) {
                prime_cap <<= 1;
                prime_list = (uint64_t *)realloc(prime_list,
                                                 prime_cap * sizeof(uint64_t));
            }
            prime_list[prime_count++] = n;
        }
    }
}

/* Test primality of an arbitrary 64‑bit integer. */
static bool is_prime_uint64(uint64_t n)
{
    if (n < 2) return false;
    if (n == 2) return true;
    if ((n & 1) == 0) return false;

    uint64_t lim = isqrt_uint64(n);
    extend_prime_list(lim);

    for (size_t i = 0; i < prime_count; ++i) {
        uint64_t p = prime_list[i];
        if (p > lim) break;
        if (n % p == 0) return false;
    }
    return true;
}

/* Check whether a prime p ≠ 2 belongs to a twin‑prime pair. */
static bool is_twin_prime(uint64_t p)
{
    if (p == 2) return false;
    /* p must be prime – the caller guarantees this. */
    return is_prime_uint64(p + 2) || (p > 2 && is_prime_uint64(p - 2));
}

/* ----------  Sequence generation  ---------- */

static seq_t *cache   = NULL;
static size_t seq_len = 0;   /* number of stored terms          */
static size_t cache_cap = 0; /* capacity of cache array         */
static uint64_t checked_max = 0;  /* largest integer already tested */

/* Test whether k satisfies the sequence condition. */
static bool admissible(uint64_t k)
{
    if (k == 1) return true;

    uint64_t n = k;
    /* Ensure primes up to sqrt(k) are known for factorisation. */
    uint64_t limit = isqrt_uint64(k);
    extend_prime_list(limit);

    for (size_t i = 0; i < prime_count; ++i) {
        uint64_t p = prime_list[i];
        if ((unsigned __int128)p * p > n) break;
        if (n % p == 0) {
            if (!is_twin_prime(p))
                return false;
            /* Remove all copies of p */
            while (n % p == 0)
                n /= p;
        }
    }
    /* Remaining factor (if any) is prime. */
    if (n > 1)
        return is_twin_prime(n);
    return true;
}

/* Lazy cache fill for the nth term. */
seq_t a(idx_t n)
{
    if (n == 0) return 0; /* out of bounds – not used by tests */

    /* Initialise on first call. */
    if (cache == NULL) {
        cache_cap = 64;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
        cache[0] = (seq_t)1;  /* a(1) = 1 */
        seq_len = 1;
        checked_max = 1;
    }

    /* Extend cache until it satisfies the demanded index. */
    while ((size_t)n > seq_len) {
        ++checked_max;
        if (checked_max > 1 && (checked_max & 1) == 0)
            continue;              /* skip even numbers > 1 */

        if (admissible(checked_max)) {
            if (seq_len == cache_cap) {
                cache_cap <<= 1;
                cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
            }
            cache[seq_len++] = (seq_t)checked_max;
        }
    }

    return cache[n - 1];
}
